import { Button } from '@/Components/ui/button';
import { cn } from '@/lib/utils';
import type { ResumeSuggestion } from '@/types';

/** The deterministic ResumeAnalysis output, shown in the workstation inspector's Suggestions tab. */
export function SuggestionList({
    suggestions,
    stale,
    onApply,
}: {
    suggestions: ResumeSuggestion[];
    stale: boolean;
    onApply: (suggestion: ResumeSuggestion) => void;
}) {
    if (suggestions.length === 0) {
        return (
            <p className="rounded-lg border border-gray-200 bg-white p-3 text-[11px] leading-relaxed text-gray-500">
                Nothing to flag. Every bullet leads with an action and carries a
                number.
            </p>
        );
    }

    return (
        <div
            className={cn(
                'flex flex-col gap-3 transition-opacity',
                stale && 'opacity-50',
            )}
            aria-busy={stale}
        >
            {suggestions.map((suggestion, index) => (
                <div
                    key={index}
                    className="flex flex-col gap-2 rounded-lg border border-gray-200 bg-white p-3"
                >
                    <p className="text-[11px] leading-relaxed text-gray-900">
                        {suggestion.message}
                    </p>
                    {suggestion.rewrite && (
                        <>
                            <p className="border-l-2 border-indigo-600 pl-2 text-[11px] leading-relaxed font-medium text-indigo-600">
                                {suggestion.rewrite}
                            </p>
                            <Button
                                variant="outline"
                                size="sm"
                                disabled={stale}
                                onClick={() => onApply(suggestion)}
                                className="self-start"
                            >
                                Insert rewrite
                            </Button>
                        </>
                    )}
                </div>
            ))}
        </div>
    );
}

import { cn } from '@/lib/utils';

function scoreLabel(score: number | null): string {
    if (score === null) {
        return 'No score yet';
    }
    if (score >= 90) return 'Excellent';
    if (score >= 75) return 'Very Good';
    if (score >= 60) return 'Good';
    if (score >= 40) return 'Fair';
    return 'Needs Work';
}

/**
 * Half-circle score gauge: a fixed red→yellow→green arc with a dot marking
 * the current score's position along it, plus the number and a band label
 * ("Very Good") inside the flat area under the arc.
 */
export function ScoreGauge({
    score,
    size = 180,
    className,
}: {
    score: number | null;
    size?: number;
    className?: string;
}) {
    const filled = score ?? 0;
    const stroke = size * 0.13;
    const radius = size / 2 - stroke / 2;
    const angleRad = ((180 - (filled / 100) * 180) * Math.PI) / 180;
    const dotX = size / 2 + radius * Math.cos(angleRad);
    const dotY = size / 2 - radius * Math.sin(angleRad);
    const dotSize = stroke * 0.7;

    return (
        <div
            className={cn('flex flex-col items-center', className)}
            style={{ width: size }}
        >
            <div
                role="img"
                aria-label={
                    score === null
                        ? 'No match score yet'
                        : `Match score ${score} of 100, ${scoreLabel(score)}`
                }
                className="relative"
                style={{ width: size, height: size / 2 }}
            >
                <div
