import { useSyncExternalStore } from 'react';

const MOBILE_BREAKPOINT = 768;

const mql =
    typeof window === 'undefined'
        ? undefined
        : window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`);

function mediaQueryListener(callback: (event: MediaQueryListEvent) => void) {
    if (!mql) {
        return () => {};
    }

    mql.addEventListener('change', callback);

    return () => {
        mql.removeEventListener('change', callback);
    };
}

function isSmallerThanBreakpoint(): boolean {
    return mql?.matches ?? false;
}

function getServerSnapshot(): boolean {
    return false;
}

export function useIsMobile(): boolean {
    return useSyncExternalStore(
        mediaQueryListener,
        isSmallerThanBreakpoint,
        getServerSnapshot,
    );
}

import { useCallback, useMemo, useState } from 'react';

type History<T> = {
    past: T[];
    present: T;
    future: T[];
    /** When the top of `past` was pushed, for coalescing. */
    pushedAt: number;
};

/**
 * `useState` with undo/redo.
 *
 * Consecutive changes inside `coalesceMs` overwrite the top of the stack
 * instead of pushing, so typing a sentence is one undo step rather than forty.
 * A pause, or any change arriving after one, starts a new step.
 *
 * The stacks live in state rather than refs deliberately: React invokes state
 * updaters twice under StrictMode, and a ref mutated inside one would record
 * every edit twice.
 */
export function useHistory<T>(initial: T, coalesceMs = 600) {
    const [history, setHistory] = useState<History<T>>({
        past: [],
        present: initial,
        future: [],
        pushedAt: 0,
    });

    const set = useCallback(
        (next: T | ((current: T) => T)) => {
            // Read the clock out here — an updater has to be pure to survive
            // being called twice.
            const now = Date.now();

            setHistory((state) => {
                const value =
                    typeof next === 'function'
                        ? (next as (current: T) => T)(state.present)
                        : next;

                if (Object.is(value, state.present)) {
                    return state;
                }

                const coalesce = now - state.pushedAt <= coalesceMs;

                return {
                    past: coalesce
                        ? state.past
                        : [...state.past, state.present],
                    present: value,
                    // Any fresh edit invalidates the redo branch.
                    future: [],
                    pushedAt: coalesce ? state.pushedAt : now,
                };
            });
        },
        [coalesceMs],
    );

    const undo = useCallback(() => {
        setHistory((state) => {
            const previous = state.past.at(-1);

            if (previous === undefined) {
                return state;
            }

            return {
                past: state.past.slice(0, -1),
                present: previous,
                future: [...state.future, state.present],
                // Start the next edit on its own step rather than coalescing
                // it into the state we just restored.
                pushedAt: 0,
            };
        });
    }, []);

    const redo = useCallback(() => {
        setHistory((state) => {
            const next = state.future.at(-1);

            if (next === undefined) {
                return state;
            }

            return {
                past: [...state.past, state.present],
                present: next,
                future: state.future.slice(0, -1),
                pushedAt: 0,
            };
        });
    }, []);

    return useMemo(
        () => ({
            value: history.present,
            set,
            undo,
            redo,
            canUndo: history.past.length > 0,
            canRedo: history.future.length > 0,
        }),
        [history, set, undo, redo],
    );
}

import { useState, useEffect } from 'react';

export function useDarkMode() {
    const [isDark, setIsDark] = useState<boolean>(() => {
        if (typeof window === 'undefined') return false;
        const stored = localStorage.getItem('theme');
        if (stored !== null) return stored === 'dark';
        return window.matchMedia('(prefers-color-scheme: dark)').matches;
    });

    useEffect(() => {
        const root = document.documentElement;
        if (isDark) {
            root.classList.add('dark');
            localStorage.setItem('theme', 'dark');
        } else {
            root.classList.remove('dark');
            localStorage.setItem('theme', 'light');
        }
    }, [isDark]);

    return { isDark, toggle: () => setIsDark((v) => !v) };
}

import type { RequestPayload } from '@inertiajs/core';
import { router } from '@inertiajs/react';
import { useEffect, useRef, useState } from 'react';
import type { SaveStatus } from '@/types';

/**
 * Debounced PUT of `data` to `url`. Local state stays authoritative — the
 * response is never read back into the editor, so a save landing mid-keystroke
 * can't clobber what the user is typing.
 */
export function useAutosave<T extends RequestPayload>(
    url: string,
    data: T,
    delay = 1500,
): SaveStatus {
    const [status, setStatus] = useState<SaveStatus>('saved');
    const initial = useRef(true);

    useEffect(() => {
        // The first run is just the server's own payload arriving.
        if (initial.current) {
            initial.current = false;

            return;
        }

        setStatus('dirty');

        const timer = setTimeout(() => {
            router.put(url, data, {
                preserveScroll: true,
                preserveState: true,
                onStart: () => setStatus('saving'),
                onSuccess: () => setStatus('saved'),
                onError: () => setStatus('error'),
            });
        }, delay);

        return () => clearTimeout(timer);
    }, [url, data, delay]);

    return status;
}

import { useMemo } from 'react';
import { emailError, phoneError } from '@/lib/contact-validation';
import type { ResumeDraft } from '@/types';

export type ContactErrors = {
    email: string | null;
    phone: string | null;
};

/**
 * Splits the draft into what the editor shows and what autosave sends.
 *
 * The resume saves as one payload, so a malformed email would 422 the whole
 * PUT and take every other edit in the same debounce window with it. Instead
 * an invalid field is sent as the value the server already holds: the payload
 * keeps its shape (no controller change), the stored value survives, and the
 * inputs keep showing what was actually typed.
 *
 * The cost is that the bad field silently stops saving, so the caller has to
 * surface `errors` somewhere the user will see it even from another section.
 *
 * `savedEmail` and `savedPhone` are passed as strings rather than as the whole
 * server prop on purpose — the page spreads that prop into a fresh object every
 * render, and an unstable dependency here would restart the autosave debounce
 * on each keystroke and never let it fire.
 */
export function useValidContact(
    draft: ResumeDraft,
    savedEmail: string,
    savedPhone: string,
): {
    payload: ResumeDraft;
    errors: ContactErrors;
} {
    const errors = useMemo<ContactErrors>(
        () => ({
            email: emailError(draft.email),
            phone: phoneError(draft.phone),
        }),
        [draft.email, draft.phone],
    );

    const payload = useMemo(() => {
        if (errors.email === null && errors.phone === null) {
            return draft;
        }

        return {
            ...draft,
            // A row written before these rules existed can hold a value the
            // server would now reject, which would block every save forever.
            // Fall back to empty, which the nullable rules accept.
            email:
                errors.email === null
                    ? draft.email
                    : emailError(savedEmail) === null
                      ? savedEmail
                      : '',
            phone:
                errors.phone === null
                    ? draft.phone
                    : phoneError(savedPhone) === null
                      ? savedPhone
                      : '',
        };
    }, [draft, errors, savedEmail, savedPhone]);

    return { payload, errors };
}

/**
 * Format checks for the two contact fields that can be wrong rather than
 * merely unusual. Both fields are optional, so empty is always valid.
 *
 * These mirror the rules in UpdateResumeRequest. The server stays the
 * authority; this exists so one typo is caught before it 422s a PUT that
 * carries the rest of the document with it.
 */

/**
 * Deliberately not RFC 5322: one @, something either side, a dot in the
 * domain, no whitespace. Anything subtler is the server's `email` rule's job —
 * a stricter regex here would reject valid addresses the server accepts, which
 * is the one failure mode this must not have.
 */
const emailShape = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** The single shape a stored phone number is allowed to take. */
const phoneShape = /^\(\d{3}\) \d{3}-\d{4}$/;

export function emailError(value: string): string | null {
    const trimmed = value.trim();

    if (trimmed === '' || emailShape.test(trimmed)) {
        return null;
    }

    return 'Enter a valid email address.';
}

/**
 * US numbers only, stored in exactly one shape: (123) 456-7890.
 *
 * Because `formatPhone` runs on every keystroke the field can only hold a
 * partial version of that shape, never a wrong one — so the only failure this
 * reports is an incomplete number.
 */
export function phoneError(value: string): string | null {
    const trimmed = value.trim();

    if (trimmed === '' || phoneShape.test(trimmed)) {
        return null;
    }

    return 'Enter a 10-digit US phone number.';
}

/**
 * Punches whatever was typed into (123) 456-7890 as it is typed.
 *
 * Digits are the only input that counts, so pasting +1 (555) 123-4567 or
 * 555.123.4567 both land on the same stored value. A leading US country code
 * is dropped rather than rejected — it is the one piece of extra input that is
 * unambiguously correct rather than a typo.
 *
 * Formatting on each keystroke rather than on blur is what keeps `phoneError`
 * simple: the field is never in a state the validator has to reason about
 * beyond "how far through the shape is it".
 */
export function formatPhone(value: string): string {
    let digits = value.replace(/\D/g, '');

    if (digits.length === 11 && digits.startsWith('1')) {
        digits = digits.slice(1);
    }

    digits = digits.slice(0, 10);

    if (digits.length <= 3) {
        // No parens until there is an area code to close, or backspacing out
        // of "(12" would re-add the "(" the user just deleted.
        return digits;
    }

    if (digits.length <= 6) {
        return `(${digits.slice(0, 3)}) ${digits.slice(3)}`;
    }

    return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`;
}

import { diffArrays, diffWords } from 'diff';

/**
 * A run of text/bullets that is either unchanged, added, or removed between
 * two versions. Covered directly by resume-diff.test.ts, matching how
 * month-year.ts is covered — a presentation-shape helper, not business logic
 * that belongs in a Support class.
 */
export type DiffPart = {
    value: string;
    added: boolean;
    removed: boolean;
};

/** Word-level diff of a paragraph, e.g. a resume's summary. */
export function diffSummary(a: string, b: string): DiffPart[] {
    return diffWords(a, b).map((part) => ({
        value: part.value,
        added: part.added ?? false,
        removed: part.removed ?? false,
    }));
}

/**
 * Whole-bullet diff of two bullet lists — each bullet is either present,
 * added, or removed, never partially highlighted.
 */
export function diffBullets(a: string[], b: string[]): DiffPart[] {
    return diffArrays(a, b).flatMap((part) =>
        part.value.map((value) => ({
            value,
            added: part.added ?? false,
            removed: part.removed ?? false,
        })),
    );
}

import type { InertiaLinkProps } from '@inertiajs/react';
import { clsx } from 'clsx';
import type { ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
    return twMerge(clsx(inputs));
}

export function toUrl(url: NonNullable<InertiaLinkProps['href']>): string {
    return typeof url === 'string' ? url : url.url;
}

/**
 * Resume dates are stored as the text the preview prints — "Jun 2019" — while
 * the editor offers them as two dropdowns. These convert between the two.
 *
 * Either half may stand alone: a resume that says only "2019" is legitimate,
 * and splitting the control shouldn't force a month out of someone who doesn't
 * want to give one.
 */

export const monthNames = [
    'Jan',
    'Feb',
    'Mar',
    'Apr',
    'May',
    'Jun',
    'Jul',
    'Aug',
    'Sep',
    'Oct',
    'Nov',
    'Dec',
];

export const firstYear = 1965;

export const lastYear = 2050;

/** Built once at module load rather than per render. */
export const years: string[] = [];

for (let year = firstYear; year <= lastYear; year++) {
    years.push(String(year));
}

const pattern = new RegExp(`^(?:(${monthNames.join('|')})\\s*)?(\\d{4})?$`);

export type MonthYear = {
    month: string;
    year: string;
    /** The original text when it fits neither dropdown; '' otherwise. */
    unparsed: string;
};

export function splitMonthYear(value: string): MonthYear {
    const match = value.trim().match(pattern);

    if (match === null) {
        return { month: '', year: '', unparsed: value };
    }

    return { month: match[1] ?? '', year: match[2] ?? '', unparsed: '' };
}

export function joinMonthYear(month: string, year: string): string {
    return [month, year].filter((part) => part !== '').join(' ');
}

import type { ResumeDraft, ResumeSectionKey } from '@/types';

export type SectionStatus = 'complete' | 'warning' | 'empty';

export const sectionLabels: Record<ResumeSectionKey, string> = {
    contact: 'Start - Main',
    summary: 'Professional Summary',
    experience: 'Experience',
    project: 'Project',
    education: 'Education',
    skills: 'Skills',
    certificate: 'Certificate',
};

/** Sections a resume is complete without. */
export const optionalSections: ResumeSectionKey[] = ['project', 'certificate'];

/**
 * Whether a section reads as done, half-done, or untouched.
 *
 * `warning` means started but missing something a reader would expect —
 * an experience with no bullets, a summary too short to say anything. It is
 * what drives both the rail's dots and the completeness percentage.
 */
export function sectionStatus(
    resume: ResumeDraft,
    section: ResumeSectionKey,
): SectionStatus {
    switch (section) {
        case 'contact': {
            const filled = [resume.full_name, resume.email].filter(Boolean);

            if (filled.length === 0) {
                return 'empty';
            }

            return filled.length === 2 && Boolean(resume.location)
                ? 'complete'
                : 'warning';
        }

        case 'summary':
            if (!resume.summary) {
                return 'empty';
            }

            return resume.summary.length >= 80 ? 'complete' : 'warning';

        case 'experience': {
            const entries = resume.experiences.filter(
                (entry) => entry.title || entry.company,
            );

            if (entries.length === 0) {
                return 'empty';
            }

            return entries.every((entry) => entry.bullets.some(Boolean))
                ? 'complete'
                : 'warning';
        }

        case 'project': {
            const entries = resume.projects.filter((entry) => entry.name);

            if (entries.length === 0) {
                return 'empty';
            }

            return entries.every((entry) => entry.description)
                ? 'complete'
                : 'warning';
        }

        case 'education': {
            const entries = resume.education.filter((entry) => entry.school);

            if (entries.length === 0) {
                return 'empty';
            }

            return entries.every((entry) => entry.degree)
                ? 'complete'
                : 'warning';
        }

        case 'skills':
            if (resume.skills.length === 0) {
                return 'empty';
            }

            return resume.skills.length >= 5 ? 'complete' : 'warning';

        case 'certificate': {
            const entries = resume.certificates.filter((entry) => entry.name);

            if (entries.length === 0) {
                return 'empty';
            }

            return entries.every((entry) => entry.issuer)
                ? 'complete'
                : 'warning';
        }
    }
}

/**
 * Share of required sections that are complete, 0-100. Optional sections count
 * only once started — adding an empty Projects section shouldn't drop the bar.
 */
export function completeness(resume: ResumeDraft): number {
    const counted = resume.section_order.filter(
        (section) =>
            !optionalSections.includes(section) ||
            sectionStatus(resume, section) !== 'empty',
    );

    if (counted.length === 0) {
        return 0;
    }

    const complete = counted.filter(
        (section) => sectionStatus(resume, section) === 'complete',
    ).length;

    return Math.round((complete / counted.length) * 100);
}

import { Menu, MenuButton, MenuItem, MenuItems } from '@headlessui/react';
import {
    ArrowsRightLeftIcon,
    ChevronDownIcon,
    DocumentDuplicateIcon,
    EllipsisVerticalIcon,
    PlusIcon,
    TrashIcon,
} from '@heroicons/react/24/outline';
import { Head, Link, router } from '@inertiajs/react';
import { useState } from 'react';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout';
import { ScoreDial } from '@/Components/resume/score-dial';
import { Button, buttonClassName } from '@/Components/ui/button';
import { Card } from '@/Components/ui/card';
import { cn } from '@/lib/utils';
import type { ResumeSummary } from '@/types';

function scoreDotColor(score: number): string {
    if (score >= 70) return 'bg-emerald-500';
    if (score >= 40) return 'bg-amber-400';
    return 'bg-gray-300';
}

function ResumeCard({ resume }: { resume: ResumeSummary }) {
    const [expanded, setExpanded] = useState(false);
    const [creatingVersion, setCreatingVersion] = useState(false);
    const hasVersions = resume.versions.length > 1;

    function createVersion() {
        if (creatingVersion) return;

        router.post(route('resumes.duplicate', resume.id), undefined, {
            onStart: () => setCreatingVersion(true),
            onFinish: () => setCreatingVersion(false),
        });
    }

    function deleteGroup() {
        if (!confirm(`Delete "${resume.title}"? This can't be undone.`)) {
            return;
        }

        router.delete(route('resume-groups.destroy', resume.group_id), {
            preserveScroll: true,
        });
    }

    function deleteVersion(versionId: number, title: string) {
        if (!confirm(`Delete "${title}"? This can't be undone.`)) {
            return;
        }

        router.delete(route('resumes.destroy', versionId), {
            preserveScroll: true,
        });
    }

    function renameGroup(title: string) {
        const trimmed = title.trim();

        if (trimmed !== '' && trimmed !== resume.title) {
            router.patch(
                route('resume-groups.update', resume.group_id),
                { title: trimmed },
                { preserveScroll: true, preserveState: true },
            );
        }
    }

    return (
        <Card className="p-0">
            <div className="flex items-center gap-4 p-4">
                <ScoreDial score={resume.score} size={48} />
                <div className="min-w-0 flex-1">
                    <Link
                        href={route('resumes.workstation', resume.id)}
                        className="truncate text-sm font-semibold text-gray-900 hover:text-indigo-600"
                    >
                        {resume.title}
                    </Link>
                    <p className="mt-0.5 truncate text-xs text-gray-500">
                        {resume.target_role || 'No target role set'}
                        {resume.updated_at && ` · Updated ${resume.updated_at}`}
                    </p>
                </div>
                <Menu as="div" className="relative">
                    <MenuButton className={buttonClassName('outline', 'sm')}>
                        Download
                        <ChevronDownIcon className="size-3.5" />
                    </MenuButton>
                    <MenuItems
                        anchor="bottom end"
                        className="z-50 w-44 rounded-md border border-gray-200 bg-white p-1 shadow-lg focus:outline-none"
                    >
                        <MenuItem>
                            <a
                                href={route('resumes.download', resume.id)}
                                className="block w-full rounded px-2 py-1.5 text-left text-sm data-focus:bg-gray-100"
                            >
                                Download PDF
                            </a>
                        </MenuItem>
                        <MenuItem>
                            <a
                                href={route('resumes.download-docx', resume.id)}
                                className="block w-full rounded px-2 py-1.5 text-left text-sm data-focus:bg-gray-100"
                            >
                                Download DOCX
                            </a>
                        </MenuItem>
                    </MenuItems>
                </Menu>
                <Link
                    href={route('resumes.workstation', resume.id)}
                    className={buttonClassName('default', 'sm')}
                >
                    Open
                </Link>
                <Menu as="div" className="relative">
                    <MenuButton
                        aria-label={`Actions for ${resume.title}`}
                        className="p-1 text-gray-500 hover:text-gray-900"
                    >
                        <EllipsisVerticalIcon className="size-5" />
                    </MenuButton>
                    <MenuItems
                        anchor="bottom end"
                        className="z-50 w-56 rounded-md border border-gray-200 bg-white p-1 shadow-lg focus:outline-none"
                    >
                        <MenuItem>
                            <button
                                type="button"
                                disabled={creatingVersion}
                                onClick={createVersion}
                                className="flex w-full items-center gap-2 rounded px-2 py-1.5 text-left text-sm data-focus:bg-gray-100 disabled:opacity-50"
                            >
                                <DocumentDuplicateIcon className="size-4" />
                                {creatingVersion ? 'Creating…' : 'New version'}
                            </button>
                        </MenuItem>
                        {hasVersions && (
                            <MenuItem>
                                <button
                                    type="button"
                                    onClick={() =>
                                        router.get(
                                            route('resume-groups.compare', resume.group_id),
                                        )
                                    }
                                    className="flex w-full items-center gap-2 rounded px-2 py-1.5 text-left text-sm data-focus:bg-gray-100"
                                >
                                    <ArrowsRightLeftIcon className="size-4" />
                                    Compare versions
                                </button>
                            </MenuItem>
                        )}
                        {!hasVersions && (
                            <MenuItem>
                                <button
                                    type="button"
                                    onClick={deleteGroup}
                                    className="flex w-full items-center gap-2 rounded px-2 py-1.5 text-left text-sm text-red-600 data-focus:bg-red-50"
                                >
                                    <TrashIcon className="size-4" />
                                    Delete resume
                                </button>
                            </MenuItem>
                        )}
                        <div className="my-1 border-t border-gray-200" />
                        <div className="px-2 py-1.5">
                            <p className="mb-1 text-[10px] font-semibold text-gray-500 uppercase">
                                Rename
                            </p>
                            <input
                                aria-label="Resume name"
                                defaultValue={resume.title}
                                maxLength={255}
                                onBlur={(event) => renameGroup(event.target.value)}
                                onKeyDown={(event) => {
                                    if (event.key === 'Enter') {
                                        event.currentTarget.blur();
                                    }
                                }}
                                className="w-full rounded border border-gray-300 px-2 py-1 text-xs"
                            />
                        </div>
                    </MenuItems>
                </Menu>
            </div>

            {hasVersions && (
                <div className="border-t border-gray-100">
                    <button
                        type="button"
                        onClick={() => setExpanded(!expanded)}
                        className="w-full px-4 py-1.5 text-left text-xs font-medium text-gray-500 hover:text-gray-900"
                    >
                        {expanded ? 'Hide' : 'Show'} {resume.versions.length} versions
                    </button>
                    {expanded && (
                        <div className="flex flex-col pb-1.5">
                            {resume.versions.map((version) => (
                                <div
                                    key={version.id}
                                    className="flex items-center gap-2.5 px-4 py-2 pl-10 hover:bg-gray-50"
                                >
                                    <span
                                        aria-hidden="true"
                                        className={cn(
                                            'size-1.5 shrink-0 rounded-full',
                                            scoreDotColor(version.score),
                                        )}
                                    />
                                    <span className="flex-1 truncate text-[12px] font-semibold">
                                        {version.title}
                                        {version.target_company && (
                                            <span className="ml-1.5 font-normal text-gray-500">
                                                — {version.target_company}
                                            </span>
                                        )}
                                    </span>
                                    <span className="text-[11px] text-gray-500">
                                        {version.score}/100
                                    </span>
                                    <Link
                                        href={route('resumes.workstation', version.id)}
                                        className={buttonClassName('outline', 'sm')}
                                    >
                                        Open
                                    </Link>
                                    <button
                                        type="button"
                                        disabled={version.is_base}
                                        onClick={() => deleteVersion(version.id, version.title)}
                                        aria-label={`Delete ${version.title}`}
                                        className="text-gray-400 hover:text-red-600 disabled:cursor-not-allowed disabled:opacity-40"
                                    >
                                        <TrashIcon className="size-4" />
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            )}
        </Card>
    );
}

export default function Dashboard({
    resumes,
    average_score,
    hasStarterProfile,
}: {
    resumes: ResumeSummary[];
    average_score: number | null;
    hasStarterProfile: boolean;
}) {
    const [creatingResume, setCreatingResume] = useState(false);

    function createResume() {
        if (creatingResume) return;

        router.post(
            route('resumes.store'),
            {},
            {
                onStart: () => setCreatingResume(true),
                onFinish: () => setCreatingResume(false),
            },
        );
    }

    return (
        <AuthenticatedLayout
            header={
                <h2 className="text-xl font-semibold text-gray-800">
                    Dashboard
                </h2>
            }
        >
            <Head title="Dashboard" />

            <div className="py-8">
                <div className="mx-auto max-w-5xl space-y-6 px-4 sm:px-6 lg:px-8">
                    {!hasStarterProfile && (
                        <Card className="border-indigo-100 bg-indigo-50/40 p-5 sm:flex-row sm:items-center sm:justify-between">
                            <div>
                                <p className="text-sm font-bold">
                                    Set up your starter profile
                                </p>
                                <p className="mt-1 text-sm text-gray-500">
                                    Fill it in once and every new resume starts
                                    pre-filled.
                                </p>
                            </div>
                            <Link
                                href={route('starter-profile.edit')}
                                className={cn(buttonClassName('outline'), 'mt-3 sm:mt-0')}
                            >
                                Set up profile
                            </Link>
                        </Card>
                    )}

                    <div className="flex items-center justify-between">
                        <div>
                            <p className="text-[10px] font-bold tracking-[0.06em] text-gray-500 uppercase">
                                Your resumes
                            </p>
                            {average_score !== null && (
                                <p className="mt-1 text-sm text-gray-500">
                                    Average score: {average_score}/100
                                </p>
                            )}
                        </div>
                        <Button disabled={creatingResume} onClick={createResume}>
                            <PlusIcon className="size-4" />
                            {creatingResume ? 'Creating…' : 'New resume'}
                        </Button>
                    </div>

                    {resumes.length === 0 ? (
                        <Card className="items-center p-10 text-center">
                            <p className="text-sm text-gray-500">
                                You haven't created a resume yet.
                            </p>
                        </Card>
                    ) : (
                        <div className="flex flex-col gap-3">
                            {resumes.map((resume) => (
                                <ResumeCard key={resume.id} resume={resume} />
                            ))}
                        </div>
                    )}
                </div>
            </div>
        </AuthenticatedLayout>
    );
}

