                        <DangerButton className="ms-3" disabled={processing}>
                            Delete Account
                        </DangerButton>
                    </div>
                </form>
            </Modal>
        </section>
    );
}

import InputError from '@/Components/InputError';
import InputLabel from '@/Components/InputLabel';
import PrimaryButton from '@/Components/PrimaryButton';
import TextInput from '@/Components/TextInput';
import { useForm } from '@inertiajs/react';
import { FormEventHandler, useState } from 'react';

interface Props {
    enabled: boolean;
    pending: boolean;
    qrCodeSvg: string | null;
    recoveryCodes: string[] | null;
    className?: string;
}

export default function TwoFactorForm({ enabled, pending, qrCodeSvg, recoveryCodes, className = '' }: Props) {
    const enableForm = useForm({});
    const confirmForm = useForm({ code: '' });
    const disableForm = useForm({});
    const regenForm = useForm({});
    const [copied, setCopied] = useState(false);

    const handleEnable: FormEventHandler = (e) => {
        e.preventDefault();
        enableForm.post(route('two-factor.enable'), { preserveScroll: true });
    };

    const handleConfirm: FormEventHandler = (e) => {
        e.preventDefault();
        confirmForm.post(route('two-factor.confirm'), { preserveScroll: true });
    };

    const handleDisable: FormEventHandler = (e) => {
        e.preventDefault();
        disableForm.delete(route('two-factor.disable'), { preserveScroll: true });
    };

    const handleRegen: FormEventHandler = (e) => {
        e.preventDefault();
        regenForm.post(route('two-factor.recovery-codes'), { preserveScroll: true });
    };

    const copyAll = () => {
        if (recoveryCodes) {
            navigator.clipboard.writeText(recoveryCodes.join('\n'));
            setCopied(true);
            setTimeout(() => setCopied(false), 2000);
        }
    };

    return (
        <section className={className}>
            <header>
                <h2 className="text-lg font-medium text-gray-900">Two-Factor Authentication</h2>
                <p className="mt-1 text-sm text-gray-600">
                    Add extra security to your account using a time-based one-time password.
                </p>
            </header>

            {/* State 1: Disabled */}
            {!enabled && !pending && (
                <form onSubmit={handleEnable} className="mt-6">
                    <PrimaryButton disabled={enableForm.processing}>
                        Enable Two-Factor Authentication
                    </PrimaryButton>
                </form>
            )}

            {/* State 2: Pending confirmation */}
            {pending && qrCodeSvg && (
                <div className="mt-6 space-y-4">
                    <p className="text-sm text-gray-600">
                        Scan this QR code with your authenticator app, then enter the 6-digit code below to confirm.
                    </p>
                    <div
                        className="inline-block rounded border border-gray-200 p-2"
                        dangerouslySetInnerHTML={{ __html: qrCodeSvg }}
                    />
                    <form onSubmit={handleConfirm} className="space-y-4">
                        <div>
                            <InputLabel htmlFor="confirm_code" value="Confirmation Code" />
                            <TextInput
                                id="confirm_code"
                                type="text"
                                inputMode="numeric"
                                value={confirmForm.data.code}
                                onChange={(e) => confirmForm.setData('code', e.target.value)}
                                className="mt-1 block w-40 tracking-widest text-center text-xl"
                                maxLength={6}
                                placeholder="000000"
                                autoComplete="one-time-code"
                            />
                            <InputError message={confirmForm.errors.code} className="mt-2" />
                        </div>
                        <PrimaryButton disabled={confirmForm.processing}>Confirm</PrimaryButton>
                    </form>
                </div>
            )}

            {/* State 3: Enabled */}
            {enabled && (
                <div className="mt-6 space-y-6">
                    <div className="flex items-center gap-2">
                        <span className="inline-flex items-center rounded-full bg-green-100 px-3 py-0.5 text-sm font-medium text-green-800">
                            Enabled
                        </span>
                        <span className="text-sm text-gray-600">Two-factor authentication is active.</span>
                    </div>

                    {recoveryCodes && recoveryCodes.length > 0 && (
                        <div className="space-y-2">
                            <p className="text-sm font-medium text-gray-700">Recovery Codes</p>
                            <p className="rounded border border-amber-200 bg-amber-50 p-2 text-sm text-amber-700">
                                Save these somewhere safe — they won't be shown again.
                            </p>
                            <pre className="rounded bg-gray-100 p-4 text-sm font-mono leading-relaxed">
                                {recoveryCodes.join('\n')}
                            </pre>
                            <button
                                type="button"
                                onClick={copyAll}
                                className="text-sm text-indigo-600 underline hover:text-indigo-800"
                            >
                                {copied ? 'Copied!' : 'Copy all'}
                            </button>
                        </div>
                    )}

                    <div className="flex gap-4">
                        <form onSubmit={handleRegen}>
                            <button
                                type="submit"
                                className="text-sm text-gray-600 underline hover:text-gray-900"
                                disabled={regenForm.processing}
                            >
                                Regenerate recovery codes
                            </button>
                        </form>

                        <form onSubmit={handleDisable}>
                            <button
                                type="submit"
                                className="text-sm text-red-600 underline hover:text-red-800"
                                disabled={disableForm.processing}
                            >
                                Disable 2FA
                            </button>
                        </form>
                    </div>
                </div>
            )}
        </section>
    );
}

import InputError from '@/Components/InputError';
import InputLabel from '@/Components/InputLabel';
import PrimaryButton from '@/Components/PrimaryButton';
import TextInput from '@/Components/TextInput';
import { Transition } from '@headlessui/react';
import { useForm } from '@inertiajs/react';
import { FormEventHandler, useRef } from 'react';

export default function UpdatePasswordForm({
    className = '',
}: {
    className?: string;
}) {
    const passwordInput = useRef<HTMLInputElement>(null);
    const currentPasswordInput = useRef<HTMLInputElement>(null);

    const {
        data,
        setData,
        errors,
        put,
        reset,
        processing,
        recentlySuccessful,
    } = useForm({
        current_password: '',
        password: '',
        password_confirmation: '',
    });

    const updatePassword: FormEventHandler = (e) => {
        e.preventDefault();

        put(route('password.change'), {
            preserveScroll: true,
            onSuccess: () => reset(),
            onError: (errors) => {
                if (errors.password) {
                    reset('password', 'password_confirmation');
                    passwordInput.current?.focus();
                }

                if (errors.current_password) {
                    reset('current_password');
                    currentPasswordInput.current?.focus();
                }
            },
        });
    };

    return (
        <section className={className}>
            <header>
                <h2 className="text-sm font-bold text-[#0f0f1a]">
                    Update Password
                </h2>

                <p className="mt-1 text-sm text-[#a0a0b0]">
                    Ensure your account is using a long, random password to stay
                    secure.
                </p>
            </header>

            <form onSubmit={updatePassword} className="mt-6 space-y-6">
                <div>
                    <InputLabel
                        htmlFor="current_password"
                        value="Current Password"
                    />

                    <TextInput
                        id="current_password"
                        ref={currentPasswordInput}
                        value={data.current_password}
                        onChange={(e) =>
                            setData('current_password', e.target.value)
                        }
                        type="password"
                        className="mt-1 block w-full"
                        autoComplete="current-password"
                    />

                    <InputError
                        message={errors.current_password}
                        className="mt-2"
                    />
                </div>

                <div>
                    <InputLabel htmlFor="password" value="New Password" />

                    <TextInput
                        id="password"
                        ref={passwordInput}
                        value={data.password}
                        onChange={(e) => setData('password', e.target.value)}
                        type="password"
                        className="mt-1 block w-full"
                        autoComplete="new-password"
                    />

                    <InputError message={errors.password} className="mt-2" />
                </div>

                <div>
                    <InputLabel
                        htmlFor="password_confirmation"
                        value="Confirm Password"
                    />

                    <TextInput
                        id="password_confirmation"
                        value={data.password_confirmation}
                        onChange={(e) =>
                            setData('password_confirmation', e.target.value)
                        }
                        type="password"
                        className="mt-1 block w-full"
                        autoComplete="new-password"
                    />

                    <InputError
                        message={errors.password_confirmation}
                        className="mt-2"
                    />
                </div>

                <div className="flex items-center gap-4">
                    <PrimaryButton disabled={processing}>Save</PrimaryButton>

                    <Transition
                        show={recentlySuccessful}
                        enter="motion-safe:transition motion-safe:ease-in-out"
                        enterFrom="opacity-0"
                        leave="motion-safe:transition motion-safe:ease-in-out"
                        leaveTo="opacity-0"
                    >
                        <p className="text-sm text-[#71717a]">
                            Saved.
                        </p>
                    </Transition>
                </div>
            </form>
        </section>
    );
}

