    public function storeSkill(Request $request): RedirectResponse
    {
        $request->validate([
            'name' => ['required', 'string', 'min:2', 'max:150'],
            'category' => ['required', 'string', 'min:2', 'max:100'],
        ]);

        JobSkill::firstOrCreate([
