function EmailGate({ token }: { token: string }) {
    const { data, setData, post, processing, errors } = useForm({ email: '' });

    const submit: FormEventHandler = (e) => {
        e.preventDefault();
        post(route('share.unlock', token));
    };

    return (
        <div className="flex min-h-screen items-center justify-center bg-gray-50 px-4">
            <Head title="Enter your email to view this resume" />

            <form
                onSubmit={submit}
                className="w-full max-w-sm rounded-xl border border-gray-200 bg-white p-6 shadow-sm"
            >
                <h1 className="text-sm font-bold text-gray-900">
                    Enter your email to view this resume
                </h1>
                <p className="mt-1 text-xs text-gray-500">
                    The sender has asked visitors to identify themselves.
                </p>

                <Input
                    type="email"
                    required
                    autoFocus
                    value={data.email}
                    onChange={(e) => setData('email', e.target.value)}
                    className="mt-4"
                    placeholder="you@example.com"
                />
                {errors.email && (
                    <p className="mt-1 text-xs text-red-600">{errors.email}</p>
                )}

                <Button type="submit" disabled={processing} className="mt-4 w-full">
                    Continue
                </Button>
            </form>
        </div>
    );
}

